", "game/state.py": """"Game state machine: Playing / Paused / GameOver.

Valid transitions mirror spec.domain_model.transitions.
"""
from enum import Enum


class GameState(str, Enum):
    PLAYING = "Playing"
    PAUSED = "Paused"
    GAMEOVER = "GameOver"


class InvalidTransition(Exception):
    pass


class GameStateMachine:
    _TRANSITIONS = {
        (GameState.PLAYING, "pause"): GameState.PAUSED,
        (GameState.PAUSED, "resume"): GameState.PLAYING,
        (GameState.PLAYING, "game_over"): GameState.GAMEOVER,
        (GameState.PAUSED, "game_over"): GameState.GAMEOVER,
    }

    def __init__(self):
        self.state: GameState = GameState.PLAYING

    def pause(self) -> None:
        self._apply("pause")

    def resume(self) -> None:
        self._apply("resume")

    def game_over(self) -> None:
        self._apply("game_over")

    def _apply(self, trigger: str) -> None:
        nxt = self._TRANSITIONS.get((self.state, trigger))
        if nxt is None:
            raise InvalidTransition(
                f"Cannot {trigger} from state {self.state.value}"
            )
        self.state = nxt

    def can(self, trigger: str) -> bool:
        return (self.state, trigger) in self._TRANSITIONS
", "game/game.py": """"Game domain model: a series of fraction questions with a score."""
from typing import List, Optional
import uuid

from question.question import Question
from game.state import GameState, GameStateMachine


class Game:
    """A game is a composition of Questions (Game --* Question)."""

    def __init__(self, questions: List[Question], qid: str = ""):
        self.id: str = qid or uuid.uuid4().hex[:12]
        self.questions: List[Question] = list(questions)
        self._score: int = 0
        self._index: int = 0
        self._answers: List[bool] = []
        self.state_machine: GameStateMachine = GameStateMachine()

    # -- class diagram methods --
    def play(self) -> None:
        """Begin/resume the round loop; no-op here (UI drives it) but keeps the API."""
        self.state_machine.state = GameState.PLAYING

    def viewScore(self) -> int:
        return self._score

    @property
    def score(self) -> int:
        return self._score

    @property
    def total(self) -> int:
        return len(self.questions)

    @property
    def current_index(self) -> int:
        return self._index

    @property
    def current_question(self) -> Optional[Question]:
        if 0 <= self._index < len(self.questions):
            return self.questions[self._index]
        return None

    def submit(self, answer_text: str) -> bool:
        q = self.current_question
        if q is None:
            raise IndexError("No current question")
        correct = q.checkAnswer(answer_text)
        self._answers.append(correct)
        if correct:
            self._score += 1
        self._index += 1
        if self._index >= len(self.questions):
            self.state_machine.game_over()
        return correct

    def pause(self) -> None:
        self.state_machine.pause()

    def resume(self) -> None:
        self.state_machine.resume()

    @property
    def is_over(self) -> bool:
        return self.state_machine.state == GameState.GAMEOVER

    @property
    def answers(self) -> List[bool]:
        return list(self._answers)

    def reviewed_questions(self) -> List[tuple]:
        """Return (question, correct?, user_was_correct) for answered items."""
        out = []
        for i, q in enumerate(self.questions):
            if i < len(self._answers):
                out.append((q, self._answers[i]))
        return out

    def rating(self) -> str:
        """Rating text driven strictly by the real result (no praise for zero)."""
        if self.total == 0:
            return "No questions"
        pct = self._score / self.total
        if pct >= 0.9:
            return "Excellent! You are a fractions star!"
        if pct >= 0.7:
            return "Great job — keep it up!"
        if pct >= 0.5:
            return "Good effort — practise a little more."
        if pct > 0:
            return "Keep practising — you'll get there!"
        return "No correct answers yet — try again!"
", "game/generator.py": """"Generate fraction questions in code; correct values are computed here.

Every question's correct answer is derived from arithmetic in this module; the
UI/tests never hard-code answers. Wrong choices are distinct and never equal to
(or value-equivalent to) the correct one.
"""
from fractions import Fraction
from random import Random
from typing import List

from question.question import Question, QuestionKind, _frac_str


def _decimal_str(f: Fraction) -> str:
    """Decimal string, rounded to at most 3 significant decimals."""
    val = f.numerator / f.denominator
    # round to 3 decimals and strip trailing zeros / dot
    s = f"{val:.3f}".rstrip("0").rstrip(".")
    return s if s else "0"


class FractionGenerator:
    def __init__(self, rng: Random = None):
        self.rng = rng or Random()

    def _random_generator(self, seed=None):
        return Random(seed) if seed is not None else self.rng

    def equivalent_question(self, rng: Random) -> Question:
        a = rng.randint(1, 9)
        b = rng.randint(2, 9)
        base = Fraction(a, b)
        factor = rng.randint(2, 6)
        correct = base * factor if rng.random() < 0.5 else base
        correct = Fraction(correct.numerator, correct.denominator)
        wrongs = set()
        while len(wrongs) < 3:
            n = rng.randint(1, 12)
            d = rng.randint(1, 12)
            w = Fraction(n, d)
            if w != base and w not in wrongs:
                wrongs.add(w)
        options = [correct] + list(wrongs)[:3]
        rng.shuffle(options)
        ci = options.index(correct)
        prompt = f"Which fraction equals {_frac_str(base)}?"
        return Question(prompt, [_frac_str(f) for f in options], ci,
                        QuestionKind.EQUIVALENT,
                        explanation=f"{_frac_str(correct)} = {_frac_str(base)}.")

    def simplify_question(self, rng: Random) -> Question:
        n = rng.randint(2, 9)
        d = rng.randint(2, 9)
        factor = rng.randint(2, 6)
        num, den = n * factor, d * factor
        correct = Fraction(n, d)
        wrongs = set()
        while len(wrongs) < 3:
            w = Fraction(rng.randint(1, 12), rng.randint(1, 12))
            if w != correct and w not in wrongs:
                wrongs.add(w)
        options = [correct] + list(wrongs)[:3]
        rng.shuffle(options)
        ci = options.index(correct)
        prompt = f"Reduce {num}/{den} to lowest terms."
        return Question(prompt, [_frac_str(f) for f in options], ci,
                        QuestionKind.SIMPLIFY,
                        explanation=f"{num}/{den} = {_frac_str(correct)}.")

    def decimal_question(self, rng: Random) -> Question:
        a = rng.randint(1, 9)
        b = rng.randint(2, 9)
        correct = Fraction(a, b)
        correct_str = _decimal_str(correct)
        wrongs = set()
        while len(wrongs) < 3:
            w = _decimal_str(Fraction(rng.randint(1, 19), rng.randint(2, 9)))
            if w != correct_str and w not in wrongs:
                wrongs.add(w)
        options = [correct_str] + list(wrongs)[:3]
        rng.shuffle(options)
        ci = options.index(correct_str)
        prompt = f"What is {a}/{b} as a decimal?"
        return Question(prompt, options, ci, QuestionKind.DECIMAL,
                        explanation=f"{a}/{b} = {correct_str}.")

    def larger_question(self, rng: Random) -> Question:
        # ensure the two operands are distinct in value to avoid ambiguity
        a = Fraction(rng.randint(1, 9), rng.randint(2, 9))
        b = Fraction(rng.randint(1, 9), rng.randint(2, 9))
        while b == a:
            b = Fraction(rng.randint(1, 9), rng.randint(2, 9))
        larger = a if a > b else b
        smaller = b if a > b else a
        wrongs = [smaller]
        # add two clearly-wrong distinct values
        while len(wrongs) < 3:
            w = Fraction(rng.randint(1, 9), rng.randint(2, 9))
            if w != larger and w not in wrongs:
                wrongs.append(w)
        options = [larger] + wrongs[:3]
        rng.shuffle(options)
        ci = options.index(larger)
        prompt = f"Which is larger: {_frac_str(a)} or {_frac_str(b)}?"
        return Question(prompt, [_frac_str(f) for f in options], ci,
                        QuestionKind.LARGER,
                        explanation=f"{_frac_str(larger)} > {_frac_str(smaller)}.")

    def generate(self, count: int, seed=None) -> List[Question]:
        rng = self._random_generator(seed)
        kinds = [
            self.equivalent_question,
            self.simplify_question,
            self.decimal_question,
            self.larger_question,
        ]
        out = []
        for i in range(count):
            out.append(rng.choice(kinds)(rng))
        return out
